ALTER TABLE "address" ADD CONSTRAINT "address_custom_label_present" CHECK ("label_kind" <> 'CUSTOM' OR "custom_label" IS NOT NULL); -- PROF-ADDR-001

-- Availability and service areas (BP §59)
