COMMENT ON COLUMN "support_ticket"."source" IS 'Source of the ticket (BP §12, §16, §61.3; OQ-021).';
COMMENT ON COLUMN "support_ticket"."is_safety" IS 'Safety-flagged ticket from an emergency/unsafe stop (BP §16; BOOK-CANCEL-006).';
COMMENT ON COLUMN "support_ticket"."description" IS 'Problem description (BP §12 C28, C29; SUP-005).';
COMMENT ON COLUMN "support_ticket"."evidence_media_ids" IS 'Evidence; refs media.media_object by ID (BP §12 C29; SUP-005).';
COMMENT ON COLUMN "support_ticket"."status" IS 'Ticket state (BP §40; OPS-ADMIN-012).';
COMMENT ON COLUMN "support_ticket"."closed_at" IS 'When it was closed (BP §40; CFG-RULE-012 SLA).';
COMMENT ON COLUMN "support_ticket"."resolution_note" IS 'Resolution note on close (BP §40; OPS-ADMIN-012).';
COMMENT ON COLUMN "support_ticket"."created_at" IS 'Row creation time (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "support_ticket"."updated_at" IS 'Last update time (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "support_ticket"."version" IS 'Optimistic-lock version; "taken by another agent" check (technical field, ARCH §5; BP §31.2).';
COMMENT ON TABLE "dispute" IS '[module support, owner A10] Formal transaction issue on a booking with an outcome (BP §25 Dispute "booking + parties", §16, §40; ARCH §6.1 fn¹; SUP-003, SUP-004; BOOK-STATUS-012).';
COMMENT ON COLUMN "dispute"."id" IS 'Primary key, UUID (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "dispute"."booking_id" IS 'Disputed booking; ref booking.booking by ID (BP §25 "booking"; SUP-003).';
COMMENT ON COLUMN "dispute"."opened_by_user_id" IS 'User who opened it; ref identity.user_account by ID (BP §25 "parties").';
COMMENT ON COLUMN "dispute"."opened_by_role" IS 'Party who opened it (BP §25 "parties"; OPS-ADMIN-010).';
COMMENT ON COLUMN "dispute"."level" IS 'Current level L2–L5 (BP §40; SUP-002).';
COMMENT ON COLUMN "dispute"."issue_type" IS 'Issue type code chosen in the structured complaint flow (BP §12 C29; SUP-005).';
COMMENT ON COLUMN "dispute"."description" IS 'Complaint text (BP §12 C29; SUP-005).';
COMMENT ON COLUMN "dispute"."evidence_media_ids" IS 'Evidence; refs media.media_object by ID (BP §12 C29; SUP-005).';
COMMENT ON COLUMN "dispute"."is_safety" IS 'Raised by a safety stop (BP §16; BOOK-CANCEL-006).';
COMMENT ON COLUMN "dispute"."support_ticket_id" IS 'Linked support ticket, if any (BP §40).';
COMMENT ON COLUMN "dispute"."outcome" IS 'Outcome; null while open (ARCH §6.1 fn¹; SUP-003).';
COMMENT ON COLUMN "dispute"."outcome_reason" IS 'Outcome reason; required with the outcome (CHECK) (BP §8.3; ROLE-003; SUP-003).';
COMMENT ON COLUMN "dispute"."decided_by_user_id" IS 'Staff user who decided; ref identity.user_account by ID (BP §40; OPS-ADMIN-010).';
COMMENT ON COLUMN "dispute"."decided_at" IS 'Decision time (SUP-003).';
COMMENT ON COLUMN "dispute"."created_at" IS 'Row creation time = opened at (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "dispute"."updated_at" IS 'Last update time (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "dispute"."version" IS 'Optimistic-lock version; "outcome already recorded" check (technical field, ARCH §5; BP §31.2).';
COMMENT ON TABLE "case_update" IS '[module support, owner A10] Case update on a ticket or dispute, sent to the parties (BP §24 "case update", §80; NOTIF-007; OPS-ADMIN-010, OPS-ADMIN-012). Exactly one of support_ticket_id / dispute_id is set (CHECK).';
COMMENT ON COLUMN "case_update"."id" IS 'Primary key, UUID (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "case_update"."support_ticket_id" IS 'Ticket the update belongs to (BP §40).';
COMMENT ON COLUMN "case_update"."dispute_id" IS 'Dispute the update belongs to (BP §40).';
COMMENT ON COLUMN "case_update"."author_user_id" IS 'Author; ref identity.user_account by ID (OPS-ADMIN-010 "author").';
COMMENT ON COLUMN "case_update"."author_role" IS 'Author role (OPS-ADMIN-010).';
COMMENT ON COLUMN "case_update"."text" IS 'Update text; must not contain payment instructions (BP §24, §30; NOTIF-007).';
COMMENT ON COLUMN "case_update"."created_at" IS 'Row creation time (technical field, ARCH §5; BP §25).';
COMMENT ON TABLE "verification_record" IS '[module trust, owner A05] One verification check/submission for a provider (BP §22, §25 Verification Record "Profile + verification state"; TRUST-VER-001…004). Only the team leader is verified (D-018).';
COMMENT ON COLUMN "verification_record"."id" IS 'Primary key, UUID (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "verification_record"."provider_profile_id" IS 'Provider being verified; ref profiles.provider_profile by ID (BP §25; D-018; INFRA-001).';
COMMENT ON COLUMN "verification_record"."requested_level" IS 'Level applied for (BP §22.1; TRUST-VER-002, TRUST-VER-003).';
COMMENT ON COLUMN "verification_record"."category_id" IS 'Category whose requirements apply; ref catalog.category by ID; null = general check (BP §22.1 risk-proportional; CFG-RULE-007; OQ-015).';
COMMENT ON COLUMN "verification_record"."document_media_ids" IS 'Uploaded documents; refs media.media_object by ID, picked with the system document picker (BP §22, §75; MEDIA-008).';
COMMENT ON COLUMN "verification_record"."status" IS 'Queue state (OPS-ADMIN-004; TRUST-VER-002).';
COMMENT ON COLUMN "verification_record"."submitted_at" IS 'When the provider submitted (OPS-ADMIN-004 "submitted at / waiting time").';
COMMENT ON COLUMN "verification_record"."decided_by_user_id" IS 'Risk/Trust staff user who decided; ref identity.user_account (BP §8.3, §8.4; ADMIN-ROLE-006).';
COMMENT ON COLUMN "verification_record"."decided_at" IS 'Decision time (OPS-ADMIN-004).';
COMMENT ON COLUMN "verification_record"."decision_reason" IS 'Reason for the decision; required, also audited (BP §8.3; ROLE-003).';
COMMENT ON COLUMN "verification_record"."created_at" IS 'Row creation time (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "verification_record"."updated_at" IS 'Last update time (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "verification_record"."version" IS 'Optimistic-lock version (technical field, ARCH §5; BP §31.2).';
COMMENT ON TABLE "provider_standing" IS '[module trust, owner A05] Current trust standing of a provider: verification level and low-rating enforcement state (BP §22.1; ARCH §6.4, §6.7; D-014; TRUST-VER-001; RATING-ENF-003…006).';
COMMENT ON COLUMN "provider_standing"."id" IS 'Primary key, UUID (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "provider_standing"."provider_profile_id" IS 'Provider; ref profiles.provider_profile by ID (BP §25; INFRA-001).';
COMMENT ON COLUMN "provider_standing"."verification_level" IS 'Current verification level; every provider starts at Basic (BP §22.1; ARCH §6.4; TRUST-VER-001; MATCH-ELIG-077).';
COMMENT ON COLUMN "provider_standing"."rating_standing" IS 'Low-rating standing (D-014; ARCH §6.7; RATING-ENF-003…005). Enforcement runs dry-run until D-017 is complete (RATING-ENF-008).';
COMMENT ON COLUMN "provider_standing"."rating_warning_count" IS 'Warnings given in the current low-rating episode; reset when the average is back at/above the threshold (D-014; RATING-ENF-004).';
COMMENT ON COLUMN "provider_standing"."rating_standing_changed_at" IS 'When the rating standing last changed; the review period counts from here (D-017; ARCH §6.7; RATING-ENF-004).';
COMMENT ON COLUMN "provider_standing"."last_rating_check_at" IS 'Last time the enforcement job evaluated this provider (D-014; RATING-ENF-003).';
COMMENT ON COLUMN "provider_standing"."created_at" IS 'Row creation time (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "provider_standing"."updated_at" IS 'Last update time (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "provider_standing"."version" IS 'Optimistic-lock version (technical field, ARCH §5; BP §31.2).';
COMMENT ON TABLE "supplier_badge" IS '[module trust, owner A05] Badge earned by a provider from a configured rule (BP §55.2, §66 Supplier Badge; TRUST-BADGE-001…014; D-010).';
COMMENT ON COLUMN "supplier_badge"."id" IS 'Primary key, UUID (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "supplier_badge"."provider_profile_id" IS 'Provider holding the badge; ref profiles.provider_profile by ID (BP §66; INFRA-001).';
COMMENT ON COLUMN "supplier_badge"."badge_type" IS 'Badge type (BP §66 "badge type"; BP §55.2).';
COMMENT ON COLUMN "supplier_badge"."service_id" IS 'Service the badge is for, e.g. Top Specialist for this service; ref catalog.service by ID (BP §55.2; TRUST-BADGE-009).';
COMMENT ON COLUMN "supplier_badge"."eligibility_rule" IS 'Config rule that granted it, key + version (BP §66 "eligibility rule"; OPS-ADMIN-022; D-010).';
COMMENT ON COLUMN "supplier_badge"."effective_from" IS 'Date the badge became effective (BP §66 "effective date").';
COMMENT ON COLUMN "supplier_badge"."expires_at" IS 'Expiry date, if any (BP §66 "expiry").';
COMMENT ON COLUMN "supplier_badge"."status" IS 'Expiry/recalculation status (BP §66).';
COMMENT ON COLUMN "supplier_badge"."source_metrics" IS 'Metrics used to compute the badge (BP §66 "source metrics"; BP §55.2 measurable facts).';
COMMENT ON COLUMN "supplier_badge"."created_at" IS 'Row creation time (technical field, ARCH §5; BP §25).';
COMMENT ON COLUMN "supplier_badge"."updated_at" IS 'Last update time (technical field, ARCH §5; BP §25).';
COMMENT ON TYPE "availability_rule_kind" IS 'Kind of availability rule (BP §59.1 weekly hours and breaks, §59.2 date-specific overrides; AVAIL-001…003).';
COMMENT ON TYPE "date_override_kind" IS 'Date-specific override type, exact list of BP §59.2 (AVAIL-003; meaning of LIMITED is open, OQ-071).';
COMMENT ON TYPE "service_area_kind" IS 'Service area kind: radius around a point or an active zone (BP §59.1 "preferred service areas and radius"; AVAIL-005).';
COMMENT ON TYPE "availability_status" IS 'Provider live availability status, exact list of BP §59.3 (ARCH §6.5; AVAIL-007).';
COMMENT ON TYPE "booking_status" IS 'Booking/job status: the 15 BP §15 statuses plus terminal REJECTED and NO_SHOW (ARCH §6.1 fn²). Reviewed, Declined and dispute outcomes are not statuses (ARCH §6.1 fn¹; OQ-009). BOOK-STATUS-001…017.';
COMMENT ON TYPE "no_show_party" IS 'Party of a no-show: customer or provider; BP §16 treats them differently (ARCH §6.1 fn²; BOOK-STATUS-017).';
COMMENT ON TYPE "price_model" IS 'How a service price is expressed (BP §4.1, §17; ARCH §5.5; CAT-SVC-001; OQ-010).';
COMMENT ON TYPE "selling_mode" IS 'Which customer flows a service allows (BP §53; ARCH §5.5; CAT-SVC-002; OQ-010). Shared type, also used by booking.';
COMMENT ON TYPE "materials_policy" IS 'Materials policy of a service (BP §4.2 "included, customer-provided or charged separately"; CAT-SVC-010).';
COMMENT ON TYPE "message_moderation_status" IS 'Delivery/moderation state of a message; content is checked before it reaches the other party (BP §20; REQ-AI-009; CHAT-003; ABUSE-008).';
COMMENT ON TYPE "config_scope" IS 'Scope a config value applies to (ARCH §5.3 "scope = global/city/category/service"; BP §42, §64).';
COMMENT ON TYPE "user_role_type" IS 'Platform role held by a user; one user can hold several (BP §25 User "has one or more roles"; ROLE-001, ROLE-002, ROLE-003).';
COMMENT ON TYPE "account_status" IS 'Account lifecycle state: blocked accounts keep their records; deletion is request → hold → anonymise (BP §26, §27; SEC-AUTH-006, SEC-AUTH-008).';
COMMENT ON TYPE "app_language" IS 'App language: English or Urdu (BP §78.1; I18N-001, I18N-002). Shared type, also used by intake, notifications and reviews.';
COMMENT ON TYPE "client_surface" IS 'Client surface a session belongs to; the admin portal has its own auth path (BP §34, §60; SEC-AUTH-005; PLAT-001).';
COMMENT ON TYPE "admin_sub_role" IS 'Admin sub-roles, exact list of BP §8.4 (ADMIN-ROLE-001…008).';
COMMENT ON TYPE "request_status" IS 'Customer request status (ARCH §6.2; BP §56, §66 "status", §79). Only the customer moves a request to SUBMITTED (BP §67, §77.3).';
COMMENT ON TYPE "requested_time_hint" IS 'Time suggestion offered to the customer: Now / Today / Later (BP §56.1 item 84; REQ-AI-004).';
COMMENT ON TYPE "ai_input_class" IS 'Class of input the AI received (BP §66 AI Interaction "prompt/input class"; OPS-ADMIN-026).';
COMMENT ON TYPE "ai_safety_state" IS 'Safety result of an AI step: content allowed or blocked by moderation/guards (BP §66 "safety/approval state", §67; REQ-AI-009, REQ-AI-010).';
COMMENT ON TYPE "ai_approval_state" IS 'Human approval of an AI suggestion; AI never acts without the user (BP §66 "safety/approval state", §67; REQ-AI-005; VOICE-003).';
COMMENT ON TYPE "location_source" IS 'How the location was obtained or corrected (BP §57.1; LOC-GEO-003: map pin, place search, saved address, manual entry; LOC-GEO-001 device location on tap).';
COMMENT ON TYPE "location_confirmation" IS 'Whether the customer confirmed the location; suggestions are never silently locked (BP §66 "confirmation status"; LOC-GEO-002, LOC-GEO-004).';
COMMENT ON TYPE "eligibility_result" IS 'Hard eligibility result (BP §54.1 rules 73–79; D-020 balance rule; MATCH-ELIG-073…079).';
COMMENT ON TYPE "availability_check" IS 'Availability result for the requested time: available, may receive it for later confirmation, or not available (BP §54.1 rule 76; MATCH-ELIG-076).';
COMMENT ON TYPE "media_kind" IS 'Media kind (ARCH §5.3 "kind = audio/video/photo/document"; BP §76).';
COMMENT ON TYPE "media_upload_status" IS 'Upload state of the object; a failed upload never loses the draft (ARCH §4 M14 "upload sessions"; MEDIA-009).';
COMMENT ON TYPE "media_scan_status" IS 'Scan/validation state (ARCH §5.3 "scan status"; BP §20 "scanned/validated"; CHAT-003).';
COMMENT ON TYPE "media_purpose" IS 'What a media file is for (BP §29 least privilege, §76; INFRA-003). Retention per purpose comes from config (D-011).';
COMMENT ON TYPE "media_sensitivity" IS 'Access class of a media file (BP §29, §75 item 97; ABUSE-010; INFRA-003).';
COMMENT ON TYPE "notification_priority" IS 'Message priority (ARCH §7 High/Medium/Low; BP §80).';
COMMENT ON TYPE "notification_channel" IS 'Delivery channel (BP §24; D-001 Firebase Cloud Messaging push).';
COMMENT ON TYPE "notification_status" IS 'Delivery state (BP §24; REL-009; ANALYTICS-008 notification delivery).';
COMMENT ON TYPE "payment_method" IS 'How the customer paid, recorded by the provider at billing (D-016, D-030; LEDGER-001; ARCH §6.8).';
COMMENT ON TYPE "payment_status" IS 'Payment status row: CASH_RECORDED for cash; PENDING → SUCCEEDED | FAILED for the gateway (BP §25 Payment "financial transaction state"; PAY-001; D-016).';
COMMENT ON TYPE "refund_status" IS 'Refund status row: issued by Finance, then confirmed or failed by the gateway (BP §25 Refund; PAY-006; SUP-004).';
COMMENT ON TYPE "ledger_entry_type" IS 'Provider ledger entry type (ARCH §6.8; D-016 cash debit / digital credit; D-021 payment to company; PAY-007 settlement; BP §26 reversal).';
COMMENT ON TYPE "ledger_direction" IS 'Ledger direction: debit lowers the provider balance, credit raises it (ARCH §6.8; LEDGER-003, LEDGER-004).';
COMMENT ON TYPE "commission_payment_status" IS '"Pay company" submission state in the Finance queue (D-021; ARCH §6.8; LEDGER-PAY-003, LEDGER-PAY-004).';
COMMENT ON TYPE "settlement_status" IS 'Settlement (payout) state (BP §13 P15, §25 Settlement "provider payout state"; PAY-007).';
COMMENT ON TYPE "payout_method_type" IS 'Payout method type: bank account or mobile wallet (BP §13 P16).';
COMMENT ON TYPE "payout_method_status" IS 'Payout method check status from the PayoutProvider interface (BP §13 P16 "compliant provider"; EXT-001; D-008).';
COMMENT ON TYPE "actor_role" IS 'Actor role on events, audits and messages (BP §15.1, §66 "actor"). Shared type, used by most modules.';
COMMENT ON TYPE "outbox_status" IS 'Outbox delivery state (ARCH §7; BP §31.2; REL-009).';
COMMENT ON TYPE "address_label_kind" IS 'Kind of saved-address label (BP §21 "Home/Office"; PROF-ADDR-001 Home, Work, custom).';
COMMENT ON TYPE "quote_status" IS 'Quote status (ARCH §6.6; BP §18, §58.2). WITHDRAWN is not offered until OQ-068 is answered.';
COMMENT ON TYPE "quote_customer_response" IS 'Customer response to a quote: accept, decline or ask for clarification (BP §18 step 60, §66 "customer response"; QUOTE-006).';
COMMENT ON TYPE "fare_line_type" IS 'Fare line type, exact list of BP §58.1 (FARE-001…011). LABOR is the only commissionable type (D-015; config commission.base_line_types = ["LABOR"]).';
COMMENT ON TYPE "fare_line_state" IS 'Fare line state: proposed, approved, rejected, final; an unapproved line is never payable (BP §58.2; ARCH §6.3; FARE-012).';
COMMENT ON TYPE "materials_class" IS 'Materials classification: included, excluded or customer-approved extra (BP §17; PRICE-005).';
COMMENT ON TYPE "review_moderation_status" IS 'Moderation state of a review; removed reviews never count for ratings (BP §19; REV-004, REV-005; RATING-ENF-002; REQ-AI-009).';
COMMENT ON TYPE "review_flag_status" IS 'State of a flag/report in the moderation queue (BP §19 "flag/report", "moderation queue"; REV-004, REV-005; OPS-ADMIN-011).';
COMMENT ON TYPE "support_level" IS 'Support level L1–L5 (BP §40; SUP-002). L1 is self-help; tickets are handled from L2 up.';
COMMENT ON TYPE "ticket_source" IS 'Where a ticket came from (BP §12 C28/C29, §16 safety stop, §61.3 callback; OPS-ADMIN-012; OQ-021).';
COMMENT ON TYPE "ticket_status" IS 'Ticket state: open until staff close it with a resolution note (BP §40; OPS-ADMIN-012).';
COMMENT ON TYPE "dispute_outcome" IS 'Dispute outcome stored on the dispute, not as a booking status (ARCH §6.1 fn¹; BP §15; SUP-003; OQ-009).';
COMMENT ON TYPE "verification_level" IS 'Provider verification level (BP §22.1; ARCH §6.4; TRUST-VER-001…004). Shared type, also used by catalog.service.';
COMMENT ON TYPE "verification_record_status" IS 'State of one verification submission in the Risk/Trust queue (BP §22; OPS-ADMIN-004; TRUST-VER-002).';
COMMENT ON TYPE "rating_standing" IS 'Low-rating enforcement standing; the number of warnings before block comes from config rating.warnings_before_block (D-014, D-017; ARCH §6.7; RATING-ENF-003…005).';
COMMENT ON TYPE "badge_type" IS 'Badge types, exact candidate list of BP §55.2 (TRUST-BADGE-001…014). Rules and thresholds come from config (D-010).';
COMMENT ON TYPE "badge_status" IS 'Badge expiry/recalculation status (BP §66 Supplier Badge "expiry/recalculation status").';
